import * as C from './core.js';
import {Store} from './storage.js';
const store=new Store();let db,page='HOME',recapDay=C.localDay(),calendarMonth=new Date(),busy=false,lastDay=C.localDay(),toastId;
const $=id=>document.getElementById(id);
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const card=body=>`<div class="bubble">${body}</div>`;
const button=(label,action,extra='',disabled=false)=>`<button type="button" class="bubble tap btn ${extra}" data-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
const time=n=>{n=Math.max(0,Math.ceil(n));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;};
const duration=n=>`${Math.floor(n/60)}m ${Math.round(n%60)}s`;
const day=()=>C.localDay();
const SKILLS=[["pullup","FIRST STRICT PULL-UP","Assisted pull-up → controlled lowering → first clean rep","Saturday · technique","Feet-supported hangs or assisted holds only if hands and shoulders are pain-free."],["muscleup","BAR MUSCLE-UP","Strict pull-ups → chest-high pulls → supported transition → bar dip","Saturday · technique","No explosive transitions until shoulders, elbows, and grip are ready."],["rope","LEGLESS ROPE CLIMB","Seated rope pulls → low rope technique → supervised higher climbs","Friday · technique","Never use lifting straps to attach to a rope. Get coaching and fall protection."],["climb","ROCK CLIMBING","Beginner top-rope or low bouldering with coaching and safe landings","Sunday or easy day","Start with footwork and balance; no need to wait for a pull-up."],["deadlift","BARBELL DEADLIFT","Light bar technique → 3 × 5 controlled → gradual weight increases","Wednesday · technique","Previous bar-only lift ~40 lb a year ago; check bar weight. No max attempts."],["carry","FARMER'S CARRY","Light two-hand carry → longer comfortable walks → heavier loads","Wednesday · technique","Begin light, with finger-friendly handles; no painful gripping."],["grip","PAIN-FREE GRIP","Neutral grips → light supported carries → gradual hang practice","Across the week","Pinky fingers bend sideways and hurt when gripping. Seek hand assessment; gloves/straps only for comfort on suitable lifting exercises."],["run","RUN + MOVE","Easy run/walk → controlled intervals → improved endurance","Existing RUNNING coach","Build gradually with recovery and enough food."]];
const SKILL_PLANS={"pullup":[{"title":"FOUNDATION","ex":[["Assisted pulldown","2 × 10 smooth reps at a controllable load"],["Feet-supported bar hold","3 × 10 seconds, no finger or shoulder pain"]]},{"title":"ASSISTED PULLING","ex":[["Assisted pull-up","3 × 5 clean reps at a suitable assistance"],["Controlled assisted lowering","3 × 3 reps, about 3 seconds down"]]},{"title":"FIRST STRICT REP","ex":[["Supported pull-up practice","3 × 5 with steadily less assistance"],["Strict pull-up","1 unassisted rep, full control and no pain"]]}],"muscleup":[{"title":"PULLING BASE","ex":[["Strict pull-ups","5 clean reps"],["Supported dip","3 × 5 pain-free reps"]]},{"title":"HIGH PULL + TRANSITION","ex":[["Chest-to-bar pull-up","3 controlled reps"],["Low-bar assisted transition","3 × 3 controlled reps with feet supported"]]},{"title":"FIRST MUSCLE-UP","ex":[["Straight-bar support","3 × 10 seconds stable"],["Muscle-up with qualified coach","1 controlled rep; no risky kipping or uncontrolled descent"]]}],"rope":[{"title":"ROPE HANDS + CORE","ex":[["Pain-free towel hold with feet supported","3 × 10 seconds"],["Seated rope pulls with feet anchored","3 × 5 controlled pulls at low height"]]},{"title":"LOW ROPE CONTROL","ex":[["Seated rope pulls","3 × 8 alternating reaches"],["Feet-assisted low rope climb","3 controlled low climbs with coach and mat"]]},{"title":"LEGLESS CLIMB","ex":[["Supervised low legless pulls","3 controlled pulls; safe immediate descent"],["Legless rope climb","1 supervised climb at safe height with fall protection"]]}],"climb":[{"title":"LEARN THE WALL","ex":[["Beginner coached climbing","2 easy routes using deliberate footwork"],["Safe downclimb / belay skills","Demonstrate gym-approved descent and spotting or belay"]]},{"title":"CONTROL + ENDURANCE","ex":[["Easy routes","3 completed routes with controlled feet"],["Resting on the wall","Pause and rebalance 3 times without panic"]]},{"title":"ROUTE MASTERY","ex":[["New graded route","Complete a suitably challenging route with good technique"],["Repeat with control","Complete again without pain and with safe descent"]]}],"deadlift":[{"title":"RELEARN THE HINGE","ex":[["Unloaded hip hinge","2 × 10 pain-free controlled reps"],["Empty training bar deadlift","3 × 5 clean reps; confirm actual bar weight"]]},{"title":"BUILD THE PATTERN","ex":[["Deadlift","3 × 5 at a comfortable verified weight, no back or finger pain"],["Controlled descent","All 15 reps with consistent bar path"]]},{"title":"PROGRESSIVE STRENGTH","ex":[["Deadlift","3 × 5 at a modestly higher weight than prior stage, clean technique"],["Recovery check","Repeat on a separate day without joint pain or excessive fatigue"]]},{"title":"135-LB LONG-TERM GOAL","ex":[["Barbell deadlift","135 lb × 5 with sound technique and qualified form check"],["Recovery","No pain, loss of control, or lingering symptoms"]]}],"carry":[{"title":"LIGHT LOAD CONTROL","ex":[["Farmer carry","2 × 15 lb for 20 metres, or lighter pain-free load"],["Standing loaded hold","3 × 15 seconds with neutral wrists"]]},{"title":"STEADY CARRY","ex":[["Farmer carry","2 × 25 lb for 20 metres, pain-free"],["Turn and stop","3 safe turns without dropping or leaning"]]},{"title":"POWER CARRY","ex":[["Farmer carry","2 × 40 lb for 30 metres with control"],["Repeat","2 comfortable rounds without painful grip"]]}],"grip":[{"title":"FINGER COMFORT FIRST","ex":[["Hand assessment","Discuss both pinkies bending inward and pain with clinician/hand therapist"],["Neutral-grip light hold","3 × 10 seconds without pain or finger forcing"]]},{"title":"FOUNDATION","ex":[["Light farmer hold","3 × 20 seconds with comfortable handles"],["Feet-supported hang","3 × 5 seconds only if cleared and painless"]]},{"title":"CLIMBING READINESS","ex":[["Feet-supported hang","3 × 15 seconds with full release control"],["Assisted pull-up grip","3 × 5 pain-free controlled reps"]]}],"run":[{"title":"EASY MOVEMENT","ex":[["Run/walk","15 minutes at conversational effort"],["Recovery","Repeat comfortably another day"]]},{"title":"BUILD ENDURANCE","ex":[["Run/walk","25 minutes at conversational effort"],["Consistent recovery","Repeat without unusual fatigue"]]},{"title":"CONTINUOUS RUN","ex":[["Easy run","10 minutes steady, or a comfortable accessible equivalent"],["Comfortable finish","No dizziness, joint pain, or excessive exhaustion"]]}]};
let selectedSkill=null;
const WEEKLY_MISSIONS=[["Baseline","Log your current weights, clean reps, running duration, and recovery."],["Consistency","Complete planned sessions with good form; record what you actually do."],["Clean reps","Improve clean reps on two exercises."],["Recovery review","Reduce training volume and reassess performance."],["Back strength I","Improve a controlled pulldown or row performance."],["Carries","Complete two pain-free controlled farmer's carries if grip is cleared."],["Push strength","Improve chest press and one comfortable shoulder movement."],["Recovery review","Review progress with lower training volume."],["Pull-up foundation","Improve assisted pull-up reps or decrease assistance."],["Deadlift technique","Complete light, controlled 3 × 5 deadlifts after learning technique."],["Back strength II","Improve pulldown and row performance."],["Recovery review","Compare strength, recovery, and optional consistent pictures."],["Running endurance","Improve comfortable run/walk duration."],["Grip development","Practice pain-free grip work according to hand assessment."],["Upper-body control","Improve assisted pull-ups or supported dips."],["Recovery review","Review performance and joint comfort."],["Back strength III","Record a clean back-exercise repetition record."],["Carrying strength","Improve a pain-free carrying distance or load."],["Climbing technique","Complete beginner routes with safe descent and controlled footwork."],["Recovery review","Adjust the next block based on records."],["Pulling strength","Improve assisted pulling or perform a strict rep if ready."],["Deadlift progress","Improve a safe deadlift performance."],["Running progress","Improve comfortable running time."],["Recovery review","Assess lifts, skills, and optional measurements."],["Back and arms","Record clean-rep improvement without unnecessary extra volume."],["Functional skills","Reassess controlled carries, core, and pulling ability."],["Final week","Assess attainable PRs across lifting, running and skills."]];
const campaignDay=()=>{const d=new Date();return Math.floor((Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())-Date.UTC(2026,9,13))/86400000)+1;};
const weekDates=i=>{const dt=n=>new Date(Date.UTC(2026,9,13+i*7+n)).toLocaleDateString(undefined,{month:'short',day:'numeric',timeZone:'UTC'});return dt(0)+' – '+dt(6);};
const DAILY_SKILL={0:'Rock climbing technique or gentle mobility only',1:'Pulling strength · existing IRON ladder',2:'Pushing strength · existing IRON ladder',3:'Optional light deadlift technique OR farmer\'s carry; swap, do not stack',4:'Core control · existing IRON ladder',5:'Optional low rope technique with coach; no legless climbing yet',6:'Supported pull-up technique; no explosive muscle-up attempts'};

let voiceOn=false,voiceReady=false,lastRunSegment='',lastRecoveryEnd=0,lastTimerRunning=false;
function say(message){if(!voiceOn||!voiceReady||!('speechSynthesis' in window))return;try{speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(message);u.rate=1.03;u.volume=1;speechSynthesis.speak(u);}catch(e){console.warn('Voice unavailable',e);}}
function cueRun(r){if(!r||!r.end||r.done)return;const seg=r.choice.segments[r.seg][0],key=r.id+':'+r.round+':'+r.seg;if(key===lastRunSegment)return;lastRunSegment=key;say(seg==='Shuttle out / back'?'Run to your marker, turn around, and run back.':seg==='Walk recovery'?'Walk. Recover.':seg==='Easy jog'||seg==='Jog'?'Jog now.':seg==='Walk'||seg==='Easy walk'?'Walk now.':seg==='Gentle mobility'?'Gentle mobility now.':seg);}
function startVoice(){if(!('speechSynthesis' in window)){notice('Speech not supported in this browser');return;}voiceOn=true;voiceReady=true;say('Voice coach enabled. Keep this app awake for spoken cues.');}
function notice(text){$('toast').textContent=text;$('toast').style.display='block';clearTimeout(toastId);toastId=setTimeout(()=>$('toast').style.display='none',2500);}
function markRecap(date){recapDay=date;db.recapSeen[date]=true;page='RECAP';}
function render(){
  const d=day(),p=C.profile(d),w=C.workout(db,d);let out='';
  if(page==='HOME')out=`<div class="stack">${card(`<div class="eyebrow">TODAY · ${C.DAY_NAMES[new Date().getDay()].toUpperCase()}</div><div class="big">${p.focus}</div><div class="muted">No forms. Follow the next instruction.</div><p class="hint">${new Date().toLocaleDateString(undefined,{month:'long',day:'numeric',year:'numeric'})}<br>Strength sets: ${C.recap(db,d).sets.length} · Running sessions: ${C.recap(db,d).runs.length}</p>`)}<div class="grid">${[['IRON','💪'],['SKILLS','✦'],['MISSIONS','◈'],['RUNNING','🏃'],['RECOVERY','♡'],['PROGRESS','▥'],['CALENDAR','✧'],['TIMER','◷']].map(([name,icon])=>button(`<span>${icon}</span>${name}`,`view:${name}`,'tile')).join('')}</div>${card(`<div class="eyebrow">OCTOBER GOAL</div><div class="big">125 lb</div><div class="muted">Lat pulldown stretch target. Form first; current weight is adjusted in IRON.</div>`)}${card(`<div class="eyebrow">FUNCTIONAL STRENGTH · TODAY</div><div class="muted">${esc(DAILY_SKILL[new Date().getDay()])}. Never add technical work onto an exhausted session.</div>${button('OPEN SKILL ROADMAP','view:SKILLS')}`)}${button('◈ VIEW WEEKLY MISSIONS','view:MISSIONS')}${button('✦ TODAY’S 10 PM RECAP','recap:today')}</div>`;
  if(page==='IRON'){
    if(!w.items.length)out=card(`<h2>Sunday: field + mobility</h2><p>No heavy lifting today. Open RUNNING for your session.</p>${button('OPEN RUNNING','view:RUNNING')}`);
    else if(w.done || w.stopped)out=card(`<div class="big">${w.done?'WORKOUT COMPLETE ✨':'WORKOUT ENDED'}</div><div>${w.done?"Today’s strength session is logged.":'Your actual sets are saved. You can resume and finish your remaining exercises.'}</div><p class="hint">${w.stopped?'Stopping safely counts as listening to your body. A partial session stays partial.':'Return tomorrow for an automatically selected focus.'}</p>${w.stopped?button('RESUME WORKOUT','resume','primary'):''}${button('VIEW PROGRESS','view:PROGRESS')}`);
    else {const x=C.nextSet(db,d),confirmed=C.loadConfirmed(db,d);out=`<div class="stack">${card(`<div class="row"><span class="eyebrow">AUTO-COACH · ${p.focus}</span><span class="pill">${w.index+1}/${w.items.length}</span></div><div class="big">${x.name}</div><div class="muted">Round ${w.round} of 3 · ${x.stage.toUpperCase()} stage</div><div class="bar" style="margin-top:15px" role="progressbar" aria-label="Strength session" aria-valuemin="0" aria-valuemax="${w.items.length*9}" aria-valuenow="${w.index*9+(w.round-1)*3+w.stage}"><div style="width:${(w.index*9+(w.round-1)*3+w.stage)/(w.items.length*9)*100}%"></div></div>`)}${card(`<div class="eyebrow">DO THIS SET NOW</div><div class="row" style="margin:12px 0"><div><div class="big emphasis">${x.actual} reps</div><div class="muted">Automatic target: ${x.target}</div></div><div style="text-align:right"><div class="big">${x.weight===0?'BODYWEIGHT':x.weight+' lb'}</div><div class="muted">${x.name==='Assisted Pull-up'?'Assistance':'Working weight'}</div></div></div><div class="actions">${button('− REP','rep:-1')}${button('+ REP','rep:1')}</div>${x.name==='Dead Bug'?'':`<div class="actions">${button('− 5 LB','weight:-5')}${button('+ 5 LB','weight:5')}</div>`}<p class="hint">${confirmed?'Load confirmed on this device.': 'This is an unverified starter estimate. Adjust to a comfortable load, then confirm once for this stage.'} Warm up separately with comfortable lighter sets before the first heavy set. Work down from 8 heavy → 10 moderate → 12 lighter reps; never jump straight to a max load. Controlled form; keep a few reps in reserve. Stop for pain. ${new Date().getDay()===6?'Technique day: use light loads.':''}</p>${confirmed?button('✓ SET COMPLETED','log','primary'):button('CONFIRM COMFORTABLE LOAD','confirm','primary')}`)}${card(`<div class="eyebrow">UP NEXT</div><p class="muted">TRIAL advances the stage, round and exercise after each completed set.</p><div class="row"><span>Today logged</span><strong>${C.recap(db,d).sets.length} sets</strong></div>`)}<div class="actions">${button('PAUSE / RECOVER','recover')}${button('SAVE & EXIT','stop')}</div></div>`;}
  }
  if(page==='RECOVERY')out=`<div class="stack">${card(`<div class="eyebrow">REST → READY → CONTINUE</div><div class="big">Take your time.</div><div class="muted">No questionnaires. No effort ratings. You decide when you’re ready.</div><div class="big" id="recovery-clock" style="text-align:center;margin:22px 0">${db.recovery.end?time((db.recovery.end-Date.now())/1000):'Ready when you are'}</div><div class="actions">${button('READY','ready','primary')}${button('MORE REST','rest')}${button('SAVE & EXIT','stop')}</div>`)}</div>`;
  if(page==='RUNNING'){
    const saved=C.recap(db,d).runs, r=db.runSession;
    if(!r && saved.length)out=`<div class="stack">${card(`<div class="eyebrow">DAILY MOVEMENT</div><div class="big">MOVEMENT SAVED ✨</div><p class="muted">${saved.reduce((a,s)=>a+s.durationSeconds,0)>0?duration(saved.reduce((a,s)=>a+s.durationSeconds,0)):''} recorded today. ${saved.some(s=>s.completed)?'Your prescribed intervals are complete.':'Your partial session is saved.'}</p><div class="actions">${button('TODAY’S RECAP','recap:today')}${button('MORE EASY MOVEMENT','run:new')}</div>`)}</div>`;
    else {const active=r||C.ensureRun(db,d),c=active.choice,seg=c.segments[active.seg];out=`<div class="stack">${card(`<div class="eyebrow">AUTOMATIC RUNNING COACH</div><div class="big">${c.name}</div><div class="muted">Round ${active.round}/${c.rounds}${active.day!==d?' · Resuming '+active.day:''}</div>${c.name==='FIELD SHUTTLES'?'<p class="hint">Use two comfortable field markers. Run out and back under control, then walk to recover. The timer is a guide, not a sprint requirement.</p>':''}<div class="big emphasis" style="text-align:center">${active.done?'INTERVALS COMPLETE':esc(seg[0].toUpperCase())}</div><div class="big" style="text-align:center" id="run-clock">${time(active.end?(active.end-Date.now())/1000:active.remaining)}</div><div class="bar" role="progressbar" aria-label="Movement intervals" aria-valuemin="0" aria-valuemax="${c.rounds*c.segments.length}" aria-valuenow="${active.completedIntervals}"><div style="width:${100*active.completedIntervals/(c.rounds*c.segments.length)}%"></div></div><p class="hint"><span id="run-elapsed">${duration(active.elapsed+(active.end?(Date.now()-active.startedAt)/1000:0))}</span> moving · ${active.completedIntervals}/${c.rounds*c.segments.length} intervals completed</p><div class="actions">${button(active.end?'PAUSE / WALK':'START / RESUME','run:toggle','primary',active.done)}${button('+ 30 SEC','run:more','',active.done)}</div><div class="actions">${button(active.done?'✓ FINISH / SAVE':'FINISH / SAVE PARTIAL','run:save')}${button('INTERVAL TIMER','view:TIMER')}</div><p class="hint">TRIAL chooses and advances intervals automatically. Keep a conversational pace. Walk instead of jogging whenever needed; no daily sprint requirement.</p>`)}${card(`<div class="eyebrow">DAILY MOVEMENT</div><div class="muted">Easy movement and recovery days stay in the plan. Increase jogging gradually only when rested and fueled.</div>`)}</div>`;}
  }
  if(page==='SKILLS'){
    const achievements=db.skillMilestones||{},progress=db.skillProgress||{};
    const current=SKILLS.find(s=>s[0]===selectedSkill);
    if(!current){
      out=`<div class="stack">${card(`<div class="eyebrow">PROJECT POLAR BEAR · FUNCTION FIRST</div><div class="big">SKILL MILESTONES</div><p class="muted">Tap a goal to see every stage, the exercises for it, and exactly what to complete before advancing. Your machine ladders remain unchanged.</p>`)}${SKILLS.map(([key,title,steps,when])=>{const stages=SKILL_PLANS[key],level=Math.min(progress[key]?.level||0,stages.length-1),finished=!!achievements[key];return card(`<div class="row"><span class="eyebrow">${esc(when)}</span><span class="pill">${finished?'ACHIEVED ✦':`STAGE ${level+1}/${stages.length}`}</span></div><div class="subhead" style="margin:10px 0">${esc(title)}</div><p class="muted">${esc(steps)}</p>${button('VIEW EXERCISES + REQUIREMENTS','skill:open:'+key,'primary')}`)}).join('')}${card(`<p class="hint">Technique first. These are training benchmarks, not medical clearance or tests you must force. Replace existing accessory work instead of stacking extra sets.</p>`)}</div>`;
    }else{
      const [key,title,,when,note]=current,stages=SKILL_PLANS[key],record=progress[key]||{level:0,checks:{}},level=Math.max(0,Math.min(record.level,stages.length-1)),finished=!!achievements[key];
      const stage=stages[level],checks=record.checks||{},all=stage.ex.every((_,i)=>checks[i]===true);
      out=`<div class="stack">${button('‹ ALL SKILLS','skill:back')}${card(`<div class="eyebrow">${esc(when)}</div><div class="big">${esc(title)}</div><p class="muted">${esc(note)}</p><div class="row"><span>Current level</span><span class="pill">${finished?'MILESTONE REACHED':`${level+1} / ${stages.length}`}</span></div><div class="bar" style="margin-top:12px"><div style="width:${finished?100:Math.round((level+Number(all))/stages.length*100)}%"></div></div>`)}${card(`<div class="eyebrow">CURRENT STAGE</div><div class="subhead">${esc(stage.title)}</div><p class="hint">Check each item only after completing it with proper form and no pain. Tap to see or undo its completion.</p>${stage.ex.map(([exercise,target],i)=>`<div style="border-top:1px solid #ffffff30;padding:12px 0"><strong>${checks[i]?'✓ ':''}${esc(exercise)}</strong><div class="muted">${esc(target)}</div><div style="margin-top:8px">${button(checks[i]?'✓ COMPLETED · UNCHECK':'MARK REQUIREMENT COMPLETE','skill:check:'+key+':'+i,checks[i]?'':'primary')}</div></div>`).join('')}${finished?'<p class="hint">Milestone reached. Keep practicing safely and gradually.</p>':all?button(level===stages.length-1?'✦ COMPLETE MILESTONE':'UNLOCK NEXT STAGE','skill:advance:'+key,'primary'):button('COMPLETE BOTH REQUIREMENTS TO UNLOCK','skill:locked','',true)}`)}${card(`<div class="eyebrow">FULL PROGRESSION</div>${stages.map((s,i)=>`<div class="row" style="padding:9px 0;border-top:1px solid #ffffff20"><span>${i<level?'✓ ':i===level?'✦ ':'○ '}${esc(s.title)}</span><span class="pill">${i<level?'CLEARED':i===level?'CURRENT':'LOCKED'}</span></div>`).join('')}${button('REVIEW EARLIER STAGE / RESET','skill:reset:'+key)}<p class="hint">Reset affects only this skill, not your actual workout logs.</p>`)}</div>`;
    }
  }
  if(page==='MISSIONS'){
    const d=campaignDay(),active=Math.max(0,Math.min(26,Math.floor((d-1)/7))),records=db.weeklyMissions||{};
    out=`<div class="stack">${card(`<div class="eyebrow">PROJECT POLAR BEAR · 190 DAYS</div><div class="big">WEEKLY MISSIONS</div><p class="muted">${d<1?'Campaign begins October 13, 2026':d>190?'Campaign finished':`DAY ${d} OF 190 · WEEK ${Math.floor((d-1)/7)+1}`}</p><div class="bar"><div style="width:${Math.max(0,Math.min(100,d/190*100))}%"></div></div><p class="hint">Complete goals with safe form. Mission status is separate from the daily workout calendar; do not make up missed work with extra sessions.</p>`)}${WEEKLY_MISSIONS.map(([name,goal],i)=>{const status=records[i]||'in-progress';return card(`<div class="row"><span class="eyebrow">WEEK ${i+1} · ${esc(weekDates(i))}</span><span class="pill">${status==='achieved'?'✓ ACHIEVED':i===active&&d>0&&d<=189?'CURRENT':status==='adjust'?'ADJUST':'IN PROGRESS'}</span></div><div class="subhead" style="margin:9px 0">${esc(name)}</div><p class="muted">${esc(goal)}</p><div class="actions">${button('✓ ACHIEVED','mission:'+i+':achieved',status==='achieved'?'current':'')}${button('IN PROGRESS','mission:'+i+':in-progress',status==='in-progress'?'current':'')}${button('ADJUST','mission:'+i+':adjust',status==='adjust'?'current':'')}</div>`)}).join('')}${card(`<div class="eyebrow">DAY 190 · APRIL 21, 2027</div><div class="subhead">FINAL EVALUATION</div><p class="muted">Compare actual lifting, pulling, carrying, running, climbing, recovery, and optional consistent photos or measurements with your baseline.</p>`)}</div>`;
  }
  if(page==='PROGRESS'){const prs=C.personalRecords(db);out=`<div class="stack">${card(`<div class="eyebrow">REAL RECORDS, NOT DEMO COUNTS</div><div class="grid" style="margin-top:10px"><div><div class="big">${db.sets.length}</div><div class="muted">Sets logged</div></div><div><div class="big">${db.runs.length}</div><div class="muted">Running sessions</div></div></div><div class="big">${Object.keys(db.completed).length} completed days</div><p class="hint">${db.sets.reduce((a,s)=>a+s.actualReps,0)} actual reps · ${duration(db.runs.reduce((a,r)=>a+(r.durationSeconds||0),0))} recorded movement</p>`)}${card(`<div class="eyebrow">PERSONAL RECORDS · WEIGHT</div>${Object.entries(prs).length?Object.entries(prs).map(([name,s])=>`<div class="row" style="border-bottom:1px solid #ffffff23;padding:13px 0"><span>${esc(name)}${name==='Assisted Pull-up'?'<br><span class="hint">Least assistance</span>':''}</span><b>${s.weight} lb × ${s.actualReps}</b></div>`).join(''):'<p class="muted">Complete a real set to start your records.</p>'}`)}${card(`<div class="eyebrow">RECENT SETS</div>${db.sets.length?db.sets.slice(-8).reverse().map(s=>`<p class="muted">${s.day} · ${esc(s.exercise)} · ${s.actualReps} × ${s.weight} lb (${s.stage})</p>`).join(''):'<p class="muted">No sets yet.</p>'}`)}<details class="bubble"><summary>Local backup</summary><p class="hint">Workout data stays on this device. Export a backup before clearing browser data. Import replaces this device’s records.</p><div class="actions">${button('EXPORT JSON','export')}${button('IMPORT JSON','import')}</div><input id="backup-input" type="file" accept="application/json,.json" class="hidden" aria-label="Import local backup"></details></div>`;}
  if(page==='CALENDAR'){
    const y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();
    const cells=Array(first).fill('<span></span>').concat(Array.from({length:days},(_,i)=>{const date=C.localDay(new Date(y,m,i+1)),status=C.dayStatus(db,date,d);return `<button class="day tap ${db.completed[date]?'done':''} ${date===d?'today':''} ${status==='planned recovery'?'rest-day':''}" data-action="recap:${date}" aria-label="${date}, ${status}" title="${status}">${i+1}${status==='planned recovery'?'<span class="rest-mark">♡</span>':''}</button>`;}));
    out=`<div class="stack">${card(`<div class="eyebrow">WORKOUT CALENDAR</div><div class="row">${button('‹','month:-1','smallbtn')}<div class="subhead">${calendarMonth.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</div>${button('›','month:1','smallbtn')}</div><div class="calendar">${['S','M','T','W','T','F','S'].map(s=>`<div class="weekday">${s}</div>`).join('')}${cells.join('')}</div><p class="hint">Glowing white = prescribed training completed. Dark = uncompleted. ♡ = planned recovery. Purple outline = today. Tap a date for its recap.</p>`)}${card(`<div class="eyebrow">TODAY’S AUTOMATIC FOCUS</div><div class="big">${p.focus}</div><p class="muted">Finish the scheduled strength and movement session for today’s tile to glow white. A safely ended partial session keeps its real records.</p>`)}</div>`;
  }
  if(page==='RECAP'){
    const r=C.recap(db,recapDay),groups={};r.sets.forEach(s=>(groups[s.exercise]??=[]).push(s));
    out=`<div class="stack"><div class="bubble recap" style="text-align:center;border:1px solid #ffffffdb;box-shadow:0 0 26px #ffffff36,inset 0 0 20px #8a62cb25"><div class="eyebrow">✝ TRIAL · POLAR BEAR ✝</div><div class="big" style="font-family:Georgia,serif;letter-spacing:2px">DAILY RECAP</div><div class="muted">${C.dayDate(recapDay).toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric',year:'numeric'})} · 10 PM CHECK-IN</div><div class="big emphasis">${r.complete?'✦ DAY COMPLETE ✦':C.profile(recapDay).items.length===0?'RECOVERY DAY':'TODAY’S TRAINING'}</div><div class="grid" style="margin:15px 0"><div><div class="big">${r.sets.length}</div><div class="muted">Sets logged</div></div><div><div class="big">${r.runs.length}</div><div class="muted">Movement sessions</div></div></div><div class="eyebrow" style="text-align:left;margin:17px 0 6px">STRENGTH · ${r.reps} ACTUAL REPS</div>${Object.keys(groups).length?Object.entries(groups).map(([name,arr])=>`<div style="text-align:left;border-top:1px solid #ffffff35;padding:9px 0"><strong>${esc(name)}</strong><div class="hint">${arr.length} sets · ${arr.reduce((a,s)=>a+s.actualReps,0)} reps total</div><div class="hint">${arr.map(s=>`${s.actualReps} × ${s.weight} lb${name==='Assisted Pull-up'?' assistance':''} (${s.stage}, R${s.round})`).join(' · ')}</div></div>`).join(''):'<div class="muted">No strength sets logged.</div>'}<div class="eyebrow" style="text-align:left;margin:16px 0 6px">RUN / WALK / SHUTTLES</div>${r.runs.length?r.runs.map(s=>`<div style="text-align:left;border-top:1px solid #ffffff35;padding:9px 0"><strong>${esc(s.name)}</strong><div class="hint">${s.completedIntervals ?? 'Not recorded'} intervals · ${Number.isFinite(s.durationSeconds)?duration(s.durationSeconds):'Time not recorded'} · ${s.completed?'Completed':'Partial'}</div></div>`).join(''):'<div class="muted">No movement session saved.</div>'}<div class="muted" style="margin-top:12px">Recorded movement time: ${duration(r.movementSeconds)}</div><div class="eyebrow" style="margin-top:15px">ONE DAY STRONGER · KEEP SHOWING UP</div></div><div class="actions">${button('‹ PREVIOUS DAY','recap:previous')}${button('NEXT DAY ›','recap:next','',recapDay>=d)}</div>${button('BACK TO HOME','view:HOME')}</div>`;
  }
  if(page==='TIMER')out=`<div class="stack">${card(`<div class="eyebrow">TIMER</div><div class="big" style="font-size:52px;text-align:center;margin:25px 0" id="timer-clock">${time(C.timerRemaining(db))}</div><div class="actions">${[30,60,90,120].map(v=>button(`${v}s`,`timer:set:${v}`)).join('')}</div><div class="actions">${button(db.timer.running?'PAUSE':'START','timer:toggle','primary')}${button('RESET','timer:reset')}${button('+ 30 SEC','timer:more')}</div>`)}</div>`;
  if(page==='HOME'||page==='RUNNING'||page==='RECOVERY'||page==='TIMER')out+=card(`<div class="eyebrow">VOICE COACH · OPTIONAL</div><p class="hint">Spoken rest and interval cues. iPhone browsers can suspend speech when the screen locks or the app is in the background. Keep this page open and the screen awake for reliable cues; use a phone alarm/watch for critical timing.</p>${button(voiceOn?'🔊 VOICE ON · TAP TO MUTE':'🔈 ENABLE VOICE CUES','voice:toggle')}${button('▶ TEST VOICE','voice:test')}`);
  $('page').innerHTML=out;$('page').setAttribute('aria-label',page);
  $('nav').innerHTML=['HOME','IRON','SKILLS','MISSIONS','RUNNING','RECOVERY','PROGRESS','CALENDAR','TIMER'].map(n=>button(n,`view:${n}`,page===n?'current':'')).join('');
  $('nav').querySelector('.current')?.setAttribute('aria-current','page');
  for(const btn of document.querySelectorAll('button'))if(busy)btn.disabled=true;
}
async function persist(){try{$('save-status').textContent='SAVING ON DEVICE';await store.save(db);$('save-status').textContent='SAVED ON DEVICE';return true;}catch(e){$('save-status').textContent='SAVE FAILED';notice('Could not save. Keep this tab open and export a backup.');console.error(e);return false;}}
async function act(action){
  if(busy)return;busy=true;const d=day();
  try {
    if(action.startsWith('view:')){page=action.slice(5);if(page==='SKILLS')selectedSkill=null;if(page==='RUNNING' && !db.runSession && !C.recap(db,d).runs.length)C.ensureRun(db,d);}
    else if(action.startsWith('mission:')){const [,iRaw,status]=action.split(':');const i=Number(iRaw);if(Number.isInteger(i)&&i>=0&&i<27&&['achieved','in-progress','adjust'].includes(status)){db.weeklyMissions ||= {};db.weeklyMissions[i]=status;notice('WEEKLY MISSION SAVED');}}
    else if(action.startsWith('skill:')){
      const [,cmd,key,index]=action.split(':');
      if(cmd==='back'){selectedSkill=null;}
      else if(cmd==='open'&&SKILL_PLANS[key]){selectedSkill=key;}
      else if(SKILL_PLANS[key]){
        db.skillProgress ||= {};db.skillMilestones ||= {};
        const record=db.skillProgress[key] ||= {level:0,checks:{}};
        const stage=SKILL_PLANS[key][record.level];
        if(cmd==='check'&&stage&&Number.isInteger(Number(index))&&Number(index)>=0&&Number(index)<stage.ex.length){record.checks[index]=!record.checks[index];}
        else if(cmd==='advance'&&stage&&stage.ex.every((_,i)=>record.checks[i]===true)){
          if(record.level===SKILL_PLANS[key].length-1){db.skillMilestones[key]=true;notice('MILESTONE REACHED ✦');}
          else {record.level++;record.checks={};notice('NEXT STAGE UNLOCKED ✦');}
        }
        else if(cmd==='reset'&&window.confirm('Reset this skill progression back to the first stage?')){record.level=0;record.checks={};db.skillMilestones[key]=false;notice('SKILL PROGRESSION RESET');}
      }
    }
    else if(action==='voice:toggle'){if(voiceOn){voiceOn=false;speechSynthesis?.cancel();notice('VOICE COACH MUTED');}else startVoice();}
    else if(action==='voice:test'){if(!voiceOn)startVoice();else say('Test. Walk. Run. Recovery complete.');}
    else if(action==='log'){if(C.logSet(db,d)){page=C.workout(db,d).done?'PROGRESS':'RECOVERY';notice(C.workout(db,d).done?'STRENGTH COMPLETE ✨':'SET SAVED · RECOVER');}}
    else if(action==='confirm'){C.confirmLoad(db,d);notice('LOAD CONFIRMED');}
    else if(action.startsWith('rep:'))C.adjustRep(db,d,Number(action.split(':')[1]));
    else if(action.startsWith('weight:'))C.adjustWeight(db,d,Number(action.split(':')[1]));
    else if(action==='recover'){if(!db.recovery.end)C.moreRest(db);page='RECOVERY';if(db.recovery.end){lastRecoveryEnd=db.recovery.end;say('Recovery timer started.');}}
    else if(action==='ready'){C.ready(db);page='IRON';}
    else if(action==='rest'){C.moreRest(db);lastRecoveryEnd=db.recovery.end;say('More recovery time added.');}
    else if(action==='stop'){if(!window.confirm('Save and exit this workout? Your ladder progress will remain available to resume.'))return;C.stopWorkout(db,d);page='IRON';notice('WORKOUT PAUSED · PROGRESS SAVED');}
     else if(action==='resume'){C.resumeWorkout(db,d);page='IRON';notice('WORKOUT RESUMED · CONTINUE YOUR LADDER');}
    else if(action==='run:new'){C.ensureRun(db,d);page='RUNNING';}
    else if(action==='run:toggle'){C.toggleRun(db);if(db.runSession?.end){lastRunSegment='';cueRun(db.runSession);}else say('Running paused.');}
    else if(action==='run:more')C.moreRun(db);
    else if(action==='run:save'){if(C.finishRun(db)){page='PROGRESS';notice('MOVEMENT SAVED ✨');}else notice('Start moving before saving a session.');}
    else if(action==='timer:toggle'){C.toggleTimer(db);say(db.timer.running?'Timer started.':'Timer paused.');}
    else if(action==='timer:reset')C.setTimer(db);
    else if(action==='timer:more')C.addTimer(db);
    else if(action.startsWith('timer:set:'))C.setTimer(db,Number(action.split(':')[2]));
    else if(action.startsWith('month:'))calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+Number(action.split(':')[1]),1);
    else if(action.startsWith('recap:')){let chosen=action.slice(6);if(chosen==='today')chosen=d;else if(chosen==='previous'||chosen==='next'){const date=C.dayDate(recapDay);date.setDate(date.getDate()+(chosen==='previous'?-1:1));chosen=C.localDay(date);}markRecap(chosen);}
    else if(action==='export'){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`kitty-quest-backup-${d}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
    else if(action==='import'){$('backup-input').click();return;}
    await persist();
  }catch(e){notice(e.message);console.error(e);}finally{busy=false;render();}
}
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(!btn)return;btn.classList.remove('pop');void btn.offsetWidth;btn.classList.add('pop');act(btn.dataset.action);});
document.addEventListener('change',async e=>{if(e.target.id!=='backup-input')return;const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Backup is too large (maximum 10 MB).');const imported=C.validateBackup(JSON.parse(await file.text()));if(!window.confirm('Replace this device’s Kitty Quest records with this backup? Export first if you want to keep them.'))return;busy=true;await store.save(imported);db=imported;notice('BACKUP RESTORED');}catch(error){notice(error.message);}finally{busy=false;render();}});
let ticking=false;
async function tick(){if(!db || ticking || busy)return;ticking=true;try{
  $('clock').textContent=new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
  let changed=false,rerender=false;
  if(day()!==lastDay){lastDay=day();calendarMonth=new Date();changed=true;rerender=true;}
  if(C.advanceRun(db)){changed=true;rerender=true;if(db.runSession?.done){say('Intervals finished.');notice('INTERVALS COMPLETE · FINISH / SAVE');}else cueRun(db.runSession);}
  if(C.tickTimer(db)){changed=true;rerender=true;say('Timer finished.');notice('TIMER COMPLETE');}
  if(db.recovery.end && Date.now()>=db.recovery.end){db.recovery.end=0;changed=true;say('Recovery timer finished. Ready when you are.');notice('READY WHEN YOU ARE');}
  if(C.recapDue(db)){markRecap(day());changed=true;rerender=true;}
  if(changed)await persist();if(rerender)render();
  if($('timer-clock'))$('timer-clock').textContent=time(C.timerRemaining(db));
  if($('recovery-clock'))$('recovery-clock').textContent=db.recovery.end?time((db.recovery.end-Date.now())/1000):'Ready when you are';
  const r=db.runSession;if(r){if($('run-clock'))$('run-clock').textContent=time(r.end?(r.end-Date.now())/1000:r.remaining);if($('run-elapsed'))$('run-elapsed').textContent=duration(r.elapsed+(r.end?(Date.now()-r.startedAt)/1000:0));}
  }finally{ticking=false;}}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')tick();});window.addEventListener('pageshow',tick);
// Avoid a second tab overwriting a running workout with an older snapshot.
async function start(){
  try{db=await store.open();C.workout(db,day());if(C.recapDue(db))markRecap(day());await persist();render();setInterval(tick,250);await tick();}
  catch(e){$('page').innerHTML=card(`<h2>Device storage unavailable</h2><p>Kitty Quest needs browser storage to keep your training safe. Open a regular Safari or Chrome tab and allow site storage.</p><p class="hint">${esc(e.message)}</p>`);$('save-status').textContent='STORAGE UNAVAILABLE';}
}
if(navigator.locks){navigator.locks.request('kitty-quest-active-tab',{ifAvailable:true},async lock=>{if(!lock){$('page').innerHTML=card('<h2>Kitty Quest is open elsewhere</h2><p>Use the other tab, or close it and reload here to protect your saved records.</p>');return;}await start();await new Promise(()=>{});});}else start();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(async reg=>{
  const announce=()=>notice('UPDATE READY · REOPEN AFTER YOUR SESSION');
  if(reg.waiting)announce();reg.addEventListener('updatefound',()=>{const next=reg.installing;next?.addEventListener('statechange',()=>{if(next.state==='installed' && navigator.serviceWorker.controller)announce();});});
  await navigator.serviceWorker.ready;$('offline-status').textContent='OFFLINE READY';
}).catch(()=>{$('offline-status').textContent='CACHE UNAVAILABLE';notice('Offline cache unavailable. Keep internet on until installed.');});}
